module {
  firrtl.module @M(in %clk: !firrtl.clock, in %rst: !firrtl.asyncreset)
}
OP builtin.module []
OP firrtl.module []

class FIRRTLSIntType(FIRRTLType):
    """``!firrtl.sint<8>`` - a two's-complement signed integer."""

    MNEMONIC = "sint"

    @property
    def is_signed(self) -> bool:
        return True


class FIRRTLClockType(FIRRTLType):
    """``!firrtl.clock`` - one wire, and never width-annotated."""

    MNEMONIC = "clock"

    def __init__(self) -> None:
        super().__init__(1)

    def __str__(self) -> str:
        return "!firrtl.clock"

    def with_width(self, width: Optional[int]) -> "FIRRTLClockType":
        return FIRRTLClockType()


class FIRRTLResetType(FIRRTLType):
    """``!firrtl.reset`` / ``!firrtl.asyncreset``."""

    MNEMONIC = "reset"

    def __init__(self, asynchronous: bool = False) -> None:
        super().__init__(1)
        self.asynchronous = bool(asynchronous)

    def __str__(self) -> str:
        return "!firrtl.asyncreset" if self.asynchronous else "!firrtl.reset"

    def with_width(self, width: Optional[int]) -> "FIRRTLResetType":
        return FIRRTLResetType(self.asynchronous)


class FIRRTLAnalogType(FIRRTLType):
    """``!firrtl.analog<1>`` - a bidirectional, non-digital net."""

    MNEMONIC = "analog"

    @property
    def is_ground(self) -> bool:
        return True

